def profile(index,specs,pin):
    records=[]
    for row in index:
        i=int(row['key'].split('_')[-1]);p=ROOT/row['raw_path'];data=p.read_bytes();receipt=p.with_suffix('.receipt.json');rc=read(receipt)
        assert core.sha(p)==rc['sha256'];assert hashlib.sha1(b'blob '+str(len(data)).encode()+bytes([0])+data).hexdigest()==row['blob_sha']
        if i not in specs:continue
        lines=data.decode().splitlines();anchors=[]
        for lo,hi,finding in specs[i]:
            assert 1<=lo<=hi<=len(lines),(row['path'],lo,hi,len(lines))
            anchors.append(dict(lines=[lo,hi],excerpt_sha256=hashlib.sha256(chr(10).join(lines[lo-1:hi]).encode()).hexdigest(),finding=finding))
        records.append(dict(source_identity=rc['url'],version_date=pin['date']+';'+pin['commit'],upstream_path=row['path'],local_copy=ref(p,'Inspected primary source'),receipt=ref(receipt,'Acquisition identity'),git_blob_sha1=row['blob_sha'],inspected_anchors=anchors,supported_claims=[a['finding'] for a in anchors],executed=False))
    return records

